<?php declare(strict_types=1);if(!defined('ABSPATH')){exit;} ?><div class="wrap"><h1>Pagos Sandbox</h1><p>Sandbox actúa aquí como pasarela y permite resolver operaciones pendientes desde administración.</p><?php if(isset($_GET['updated'])):?><div class="notice notice-success is-dismissible"><p>Operación procesada.</p></div><?php endif; ?><nav class="nav-tab-wrapper"><?php foreach(['pending'=>'Pendientes','paid'=>'Aprobados','failed'=>'Fallidos','cancelled'=>'Cancelados','all'=>'Todos'] as $key=>$label): ?><a class="nav-tab <?php echo $status===$key?'nav-tab-active':''; ?>" href="<?php echo esc_url(add_query_arg(['page'=>'optigrid-sandbox-payments','status'=>$key],admin_url('admin.php'))); ?>"><?php echo esc_html($label); ?></a><?php endforeach; ?></nav><table class="widefat striped"><thead><tr><th>Orden</th><th>Usuario</th><th>Plan</th><th>Importe</th><th>Fecha</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php if($orders===[]): ?><tr><td colspan="7">No hay operaciones.</td></tr><?php else: foreach($orders as $o): ?><tr><td><code><?php echo esc_html((string)$o['public_id']); ?></code></td><td><?php echo esc_html((string)($o['user_login']??$o['user_email']??$o['user_id'])); ?></td><td><?php echo esc_html((string)($o['plan_name']??$o['plan_id'])); ?></td><td><?php echo esc_html(number_format_i18n((float)$o['amount'],2).' '.strtoupper((string)$o['currency'])); ?></td><td><?php echo esc_html((string)$o['created_at']); ?></td><td><?php echo esc_html((string)$o['status']); ?></td><td><?php if($o['status']==='pending'): ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" style="display:flex;gap:6px;flex-wrap:wrap"><input type="hidden" name="action" value="<?php echo esc_attr(OptiGrid_Subscriptions_Sandbox_Payments_Controller::action()); ?>"><input type="hidden" name="order" value="<?php echo esc_attr((string)$o['public_id']); ?>"><?php wp_nonce_field('sandbox_admin_'.(string)$o['public_id']); ?><button class="button button-primary" name="scenario" value="approved">Aprobar</button><button class="button" name="scenario" value="rejected">Rechazar</button><button class="button" name="scenario" value="cancelled">Cancelar</button><button class="button" name="scenario" value="technical_error">Error</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div>
